// elevator_logic.js — pure elevator scheduler/state machine.
// No Three.js, no DOM, no canvas. Runs in the browser (window.ElevatorLogic)
// and under Node (module.exports) for elevator_logic_test.js.
//
// Exactly five states:
//   IDLE -> MOVING -> DOOR_OPENING -> DOOR_OPEN -> DOOR_CLOSING -> (IDLE | MOVING)
//
// SCAN scheduling rules implemented here (and nowhere else):
//  - direction-aware target selection with mid-trip shortening
//  - passenger destinations outrank same-floor hall calls (no full-car
//    lobby starvation during the morning rush)
//  - a served floor cannot reopen while riders/destinations remain
//  - doors only close once pending boarders/disembarkers drain AND
//    MIN_DOOR_OPEN_S has elapsed; MAX_DOOR_OPEN_S is a hard safety cap

(function (root) {
    "use strict";

    const STATES = {
        IDLE: "IDLE",
        MOVING: "MOVING",
        DOOR_OPENING: "DOOR_OPENING",
        DOOR_OPEN: "DOOR_OPEN",
        DOOR_CLOSING: "DOOR_CLOSING"
    };

    const DOOR_ANIM_S = 1.2;      // door opening/closing duration (seconds)
    const MIN_DOOR_OPEN_S = 2.0;  // doors stay open at least this long
    const MAX_DOOR_OPEN_S = 12.0; // safety cap even if a boarder never completes
    const SPEED = 2.2;            // car speed, world units per second

    // Logical interior spots (car-local coordinates; car floor at y=0).
    const SPOT_POSITIONS = [
        { x: -0.7, y: 0, z: -0.7 },
        { x: 0.7, y: 0, z: -0.7 },
        { x: -0.7, y: 0, z: 0.45 },
        { x: 0.7, y: 0, z: 0.45 }
    ];

    class ElevatorLogic {
        constructor(opts) {
            opts = opts || {};
            this.floorCount = opts.floorCount !== undefined ? opts.floorCount : 6;
            this.maxCapacity = opts.maxCapacity !== undefined ? opts.maxCapacity : 4;
            this.floorHeight = opts.floorHeight !== undefined ? opts.floorHeight : 3.4;

            this.DOOR_ANIM_S = DOOR_ANIM_S;
            this.MIN_DOOR_OPEN_S = MIN_DOOR_OPEN_S;
            this.MAX_DOOR_OPEN_S = MAX_DOOR_OPEN_S;
            this.SPEED = SPEED;

            this.reset();
        }

        reset() {
            this.state = STATES.IDLE;
            this.y = 0;                    // car floor world height
            this.currentFloor = 0;
            this.targetFloor = null;
            this.direction = 0;            // +1 up, -1 down, 0 idle
            this.upCalls = new Set();
            this.downCalls = new Set();
            this.destinations = new Set(); // floors passengers are riding to

            this.passengers = [];          // { floorIdx, spot, boarding, disembarking }
            this.pendingBoarders = new Set();
            this.pendingDisembark = new Set();

            this.doorPhase = 0;            // 0 closed .. 1 fully open
            this.doorOpenTimer = 0;

            this._lastY = 0;
            this._moving = false;
            this._servedThisDoorCycle = false;   // true while the car is at a floor
            this._lastServedFloor = -1;
        }

        // ---------------- public API ----------------

        callUp(floor) {
            if (floor >= 0 && floor < this.floorCount) this.upCalls.add(floor);
        }

        callDown(floor) {
            if (floor >= 0 && floor < this.floorCount) this.downCalls.add(floor);
        }

        pressDestination(floor) {
            if (floor >= 0 && floor < this.floorCount && floor !== null) {
                if (floor !== this.currentFloor || this.state === STATES.MOVING) {
                    this.destinations.add(floor);
                } else if (this.state !== STATES.DOOR_OPEN && this.state !== STATES.DOOR_OPENING) {
                    this.destinations.add(floor);
                }
            }
        }

        isAcceptingAt(floor, direction) {
            if (this.state !== STATES.DOOR_OPEN || this.currentFloor !== floor) return false;
            if (direction !== 0 && this.direction !== direction) return false;
            return true;
        }

        currentCapacityFree() {
            return this.maxCapacity - this.passengers.length;
        }

        _spotTaken(spot, ignore) {
            for (let i = 0; i < this.passengers.length; i++) {
                if (this.passengers[i] !== ignore && this.passengers[i].spot === spot) return true;
            }
            return false;
        }

        _spotFreeFor(spot, ignore) {
            return !this._spotTaken(spot, ignore);
        }

        // Boarders grab a logical spot while still in the hall (phase 0 of
        // boarding). This freezes the queue: the car cannot leave while
        // pendingBoarders is non-empty.
        reserveBoardingSpot(p) {
            if (this.state !== STATES.DOOR_OPEN) return false;
            if (this.passengers.length >= this.maxCapacity) return false;
            for (let i = 0; i < this.passengers.length; i++) {
                if (this.passengers[i] === p) return true;
            }
            const spot = this.passengers.length;
            if (spot >= SPOT_POSITIONS.length) return false;
            if (this._spotTaken(spot, p)) return false;
            p.spot = spot;
            p.boarding = true;
            this.pendingBoarders.add(p);
            return true;
        }

        completeBoard(p) {
            const i = this.passengers.indexOf(p);
            if (i === -1) return false;
            p.boarding = false;
            this.pendingBoarders.delete(p);
            return true;
        }

        // Disembarkers register BEFORE the door closes; the car holds the
        // doors open until they have left the car space.
        registerDisembark(p) {
            const i = this.passengers.indexOf(p);
            if (i === -1) return false;
            p.disembarking = true;
            this.pendingDisembark.add(p);
            return true;
        }

        completeDisembark(p) {
            if (!this.pendingDisembark.has(p)) return false;
            const i = this.passengers.indexOf(p);
            if (i === -1) return false;
            p.disembarking = false;
            this.pendingDisembark.delete(p);
            this.passengers.splice(i, 1);
            return true;
        }

        spotPos(i) { return SPOT_POSITIONS[i]; }

        spotWorldPos(p) {
            const s = SPOT_POSITIONS[p.spot];
            return { x: s.x, y: this.y, z: s.z };
        }

        // ---------------- door lifecycle ----------------

        _openDoors() {
            this.state = STATES.DOOR_OPENING;
            this.doorOpenTimer = 0;
        }

        _closeDoors() {
            this.state = STATES.DOOR_CLOSING;
        }

        // Called by the visual layer at the moment the door visually reaches
        // fully open (doorPhase >= 1).
        onDoorsFullyOpen() {
            if (this.state === STATES.DOOR_OPENING) {
                this.state = STATES.DOOR_OPEN;
                this._lastServedFloor = this.currentFloor;
            }
        }

        // Called by the visual layer at the moment the door visually reaches
        // fully closed (doorPhase <= 0).
        onDoorsFullyClosed() {
            if (this.state !== STATES.DOOR_CLOSING) return;
            if (this._pickNextTarget() !== null) {
                this.state = STATES.MOVING;
            } else {
                this.state = STATES.IDLE;
            }
        }

        // ---------------- targeting (SCAN) ----------------

        _arriveServe() {
            this.targetFloor = null;
            this.currentFloor = Math.round(this.y / this.floorHeight);
            if (this.direction > 0) { this.upCalls.delete(this.currentFloor); }
            else if (this.direction < 0) { this.downCalls.delete(this.currentFloor); }
            else {
                // idle arrival: honor whichever call is present
                if (this.upCalls.has(this.currentFloor)) {
                    this.upCalls.delete(this.currentFloor);
                    this.direction = 1;
                } else if (this.downCalls.has(this.currentFloor)) {
                    this.downCalls.delete(this.currentFloor);
                    this.direction = -1;
                } else {
                    this.direction = 0;
                }
            }
            // clear destinations for this floor
            this.destinations.delete(this.currentFloor);
            this._servedThisDoorCycle = true;
            this._openDoors();
        }

