        // Returns next floor to move to, or null if no work remains.
        // Priority:
        //  1. while a door cycle is in progress (we just served a floor),
        //     do NOT pick a target unless riders/destinations demand it
        //  2. direction-aware scan for the nearest call/destination in the
        //     current direction (mid-trip shortening is re-evaluated in tick)
        _pickNextTarget() {
            const hasRiders = this.passengers.length > 0;
            if (!hasRiders && this._servedThisDoorCycle) {
                // door cycle just finished at this floor; stay until a NEW
                // call arrives (prevents immediate reopen starvation)
                if (this.upCalls.size === 0 && this.downCalls.size === 0) return null;
            }

            const f0 = this.currentFloor;

            // passengers riding: nearest destination in current direction
            if (hasRiders) {
                let best = null;
                for (const d of this.destinations) {
                    if (this.direction >= 0 && d >= f0) {
                        if (best === null || d < best) best = d;
                    } else if (this.direction < 0 && d <= f0) {
                        if (best === null || d > best) best = d;
                    }
                }
                if (best !== null) {
                    if (best > f0) this.direction = 1;
                    else if (best < f0) this.direction = -1;
                    this.targetFloor = best;
                    this._servedThisDoorCycle = false;
                    return best;
                }
                // riders on board but their destination is behind us:
                // reverse direction to serve them
                for (const d of this.destinations) {
                    if (best === null ||
                        ((this.direction === 0 ? true : this.direction > 0) && d > f0 && (best === null || d < best)) ||
                        ((this.direction === 0 ? true : this.direction < 0) && d < f0 && (best === null || d > best))) {
                        best = d;
                    }
                }
                if (best !== null) {
                    if (best > f0) this.direction = 1;
                    else if (best < f0) this.direction = -1;
                    this.targetFloor = best;
                    this._servedThisDoorCycle = false;
                    return best;
                }
            }

            // hall calls in current direction
            if (this.direction >= 0) {
                let best = null;
                for (const c of this.upCalls) {
                    if (c > f0 && (best === null || c < best)) best = c;
                }
                if (best !== null) {
                    this.direction = 1;
                    this.targetFloor = best;
                    this._servedThisDoorCycle = false;
                    return best;
                }
            }
            if (this.direction <= 0) {
                let best = null;
                for (const c of this.downCalls) {
                    if (c < f0 && (best === null || c > best)) best = c;
                }
                if (best !== null) {
                    this.direction = -1;
                    this.targetFloor = best;
                    this._servedThisDoorCycle = false;
                    return best;
                }
            }

            // no directional work: allow a direction change to reach any
            // pending call/destination (classic SCAN wrap)
            if (this.direction === 0) {
                let best = null;
                for (const d of this.destinations) {
                    if (best === null || Math.abs(d - f0) < Math.abs(best - f0)) best = d;
                }
                for (const c of this.upCalls) {
                    if (best === null || Math.abs(c - f0) < Math.abs(best - f0)) best = c;
                }
                for (const c of this.downCalls) {
                    if (best === null || Math.abs(c - f0) < Math.abs(best - f0)) best = c;
                }
                if (best !== null && best !== f0) {
                    this.direction = best > f0 ? 1 : -1;
                    this.targetFloor = best;
                    this._servedThisDoorCycle = false;
                    return best;
                }
                if (best === f0) {
                    // call at current floor: open doors here
                    this.targetFloor = f0;
                    this._servedThisDoorCycle = false;
                    return f0;
                }
            }

            return null;
        }

        // ---------------- simulation step ----------------

        tick(dt) {
            dt = Math.max(0, Math.min(dt, 0.5));
            let remaining = dt;

            while (remaining > 0) {
                const step = Math.min(remaining, 1 / 30);
                remaining -= step;

                if (this.state === STATES.IDLE) {
                    // a new call may have arrived since we last checked
                    if (this.upCalls.size > 0 || this.downCalls.size > 0 ||
                        this.destinations.size > 0) {
                        this._servedThisDoorCycle = false;
                    }
                    const t = this._pickNextTarget();
                    if (t !== null) {
                        if (t === this.currentFloor) {
                            // call at our floor: open doors in place
                            this.state = STATES.MOVING;
                            this.targetFloor = this.currentFloor;
                            this.y = this.currentFloor * this.floorHeight;
                            // will _arriveServe next iteration
                        } else {
                            this.state = STATES.MOVING;
                        }
                    }
                } else if (this.state === STATES.MOVING) {
                    this._lastY = this.y;
                    const dir = this.direction > 0 ? 1 : this.direction < 0 ? -1 : 0;
                    if (dir === 0) {
                        const t = this._pickNextTarget();
                        if (t !== null) {
                            this.direction = t > this.currentFloor ? 1 : t < this.currentFloor ? -1 : 0;
                        } else {
                            // no work: settle to idle (doors closed)
                            this.state = STATES.IDLE;
                            this.direction = 0;
                            continue;
                        }
                    }
                    const d = dir * this.SPEED * step;
                    this.y += d;
                    // re-evaluate mid-trip: a nearer same-direction stop may
                    // have appeared (mid-trip shortening); also cap at target
                    const target = this.targetFloor * this.floorHeight;
                    if (dir > 0 && this.y >= target) { this.y = target; this._arriveServe(); }
                    else if (dir < 0 && this.y <= target) { this.y = target; this._arriveServe(); }
                    else {
                        // check for a closer stop in the direction of travel
                        const f0 = this.currentFloor;
                        let shorter = null;
                        if (this.direction > 0) {
                            const yF = this.y / this.floorHeight;
                            for (const d2 of this.destinations) {
                                if (d2 > f0 && d2 < this.targetFloor && (shorter === null || d2 < shorter)) shorter = d2;
                            }
                            for (const c of this.upCalls) {
                                if (c > f0 && c < this.targetFloor && (shorter === null || c < shorter)) shorter = c;
                            }
                        } else if (this.direction < 0) {
                            for (const d2 of this.destinations) {
                                if (d2 < f0 && d2 > this.targetFloor && (shorter === null || d2 > shorter)) shorter = d2;
                            }
                            for (const c of this.downCalls) {
                                if (c < f0 && c > this.targetFloor && (shorter === null || c > shorter)) shorter = c;
                            }
                        }
                        if (shorter !== null) {
                            this.targetFloor = shorter;
                            // continue moving; the target cap above will fire
                        }
                    }
                    if (this.y < 0) this.y = 0;
                    const max = (this.floorCount - 1) * this.floorHeight;
                    if (this.y > max) this.y = max;
                } else if (this.state === STATES.DOOR_OPENING) {
                    this.doorPhase += step / this.DOOR_ANIM_S;
                    if (this.doorPhase >= 1) {
                        this.doorPhase = 1;
                        this.state = STATES.DOOR_OPEN;
                        this._lastServedFloor = this.currentFloor;
                        // yield the moment the door reaches DOOR_OPEN so the
                        // rider gets at least one full frame before the
                        // MIN_DOOR_OPEN_S timer starts running
                        break;
                    }
                } else if (this.state === STATES.DOOR_OPEN) {
                    this.doorOpenTimer += step;
                    const canClose = this.pendingBoarders.size === 0 &&
                        this.pendingDisembark.size === 0 &&
                        this.doorOpenTimer >= this.MIN_DOOR_OPEN_S;
                    if (canClose || this.doorOpenTimer >= this.MAX_DOOR_OPEN_S) {
                        this._closeDoors();
                    }
                } else if (this.state === STATES.DOOR_CLOSING) {
                    this.doorPhase -= step / this.DOOR_ANIM_S;
                    if (this.doorPhase <= 0) {
                        this.doorPhase = 0;
                        this.state = STATES.MOVING;
                        this._servedThisDoorCycle = true;
                        const t = this._pickNextTarget();
                        if (t === null) {
                            this.state = STATES.IDLE;
                            this.direction = 0;
                        }
                    }
                }
            }

            this._moving = (this.state === STATES.MOVING);
        }

        getState() {
            return {
                state: this.state,
                y: this.y,
                currentFloor: this.currentFloor,
                targetFloor: this.targetFloor,
                direction: this.direction,
                doorPhase: this.doorPhase,
                upCalls: Array.from(this.upCalls).sort((a, b) => a - b),
                downCalls: Array.from(this.downCalls).sort((a, b) => a - b),
                destinations: Array.from(this.destinations).sort((a, b) => a - b),
                passengers: this.passengers.length,
                pendingBoarders: this.pendingBoarders.size,
                pendingDisembark: this.pendingDisembark.size
            };
        }
    }

    root.ElevatorLogic = ElevatorLogic;
    root.ElevatorStates = STATES;
    root.ElevatorSpots = SPOT_POSITIONS;
    if (typeof module !== "undefined" && module.exports) {
        module.exports = { ElevatorLogic, STATES: STATES, SPOT_POSITIONS: SPOT_POSITIONS };
    }
})(typeof window !== "undefined" ? window : globalThis);
