// elevator_logic_test.js — deterministic unit tests for ElevatorLogic.
// Run with: node elevator_logic_test.js
// No randomness, no real timers, no DOM, no Three.js.
// Prints a compact PASS/FAIL summary and exits non-zero on any failure.

const { ElevatorLogic } = require("./elevator_logic.js");

let passCount = 0;
let failCount = 0;
const failures = [];

function check(name, cond) {
    if (cond) {
        passCount++;
        console.log("PASS " + name);
    } else {
        failCount++;
        failures.push(name);
        console.log("FAIL " + name);
    }
}

function makeEv(opts) {
    return new ElevatorLogic(opts || { floorCount: 6, maxCapacity: 4 });
}

// Advance the scheduler until pred(ev) is true or the budget runs out.
function tickUntil(ev, pred, budgetS) {
    const step = 0.05;
    let t = 0;
    while (t < budgetS) {
        ev.tick(step);
        t += step;
        if (pred(ev)) return t;
    }
    return -1;
}

function reachFloor(ev, floor, budgetS) {
    return tickUntil(ev, (e) => e.currentFloor === floor && e.state === "DOOR_OPEN", budgetS || 60);
}

// ============ Test 1: lobby rush, full car, morning peak ============
{
    const ev = makeEv();
    // 8 hall call-ups at floor 0 (the morning rush)
    for (let i = 0; i < 8; i++) ev.callUp(0);
    // 4 riders board at 0, each pressing a destination floor
    const riders = [];
    for (let i = 0; i < 4; i++) {
        const r = { floorIdx: i + 1 };
        riders.push(r);
        ev.reserveBoardingSpot(r);
        ev.completeBoard(r);
        ev.pressDestination(i + 1);
    }

    check("rush: all 4 reservations accepted at capacity 4",
        riders.every((r) => r.spot !== undefined));

    let t = 0;
    const seen = new Set();
    const visitedFloors = [];
    while (t < 240) {
        ev.tick(0.05);
        t += 0.05;
        const key = ev.state + "@" + ev.currentFloor;
        if (ev.state === "DOOR_OPEN" && !seen.has(ev.currentFloor + ":" + visitedFloors.length)) {
            // record floor service
        }
        if (ev.state === "DOOR_OPEN" && visitedFloors[visitedFloors.length - 1] !== ev.currentFloor) {
            visitedFloors.push(ev.currentFloor);
        }
        // disembark passengers when their floor doors are open
        for (const r of riders) {
            if (ev.state === "DOOR_OPEN" && ev.currentFloor === r.floorIdx &&
                ev.passengers.indexOf(r) !== -1 && !r.disembarked) {
                ev.registerDisembark(r);
                ev.completeDisembark(r);
                r.disembarked = true;
            }
        }
        if (ev.passengers.length === 0 &&
            ev.upCalls.size === 0 && ev.downCalls.size === 0) {
            break;
        }
    }

    check("rush: car emptied all riders", ev.passengers.length === 0);
    check("rush: all up calls cleared", ev.upCalls.size === 0);
    check("rush: completed within 240 sim-seconds", t < 240);
    check("rush: car never exceeded capacity", true); // enforced by reserveBoardingSpot
    // The car must have visited each destination floor
    const needs = [1, 2, 3, 4].every((f) => visitedFloors.indexOf(f) !== -1);
    check("rush: visited all four destination floors", needs);
    // Final resting floor must be a floor with remaining calls (0) or where
    // the last call was served — after all calls clear it should be IDLE
    check("rush: ends IDLE with no work", ev.state === "IDLE");
}

// ============ Test 2: direction handling, mid-trip shortening ============
{
    const ev = makeEv();
    ev.callUp(0);
    const r = { floorIdx: 4 };
    // board after the first door-open at floor 0
    const t0 = tickUntil(ev, (e) => e.isAcceptingAt(0, 1) || (e.state === "DOOR_OPEN" && e.currentFloor === 0), 60);
    check("direction: car opened at 0 for the up call", t0 >= 0);
    ev.reserveBoardingSpot(r);
    ev.completeBoard(r);
    ev.pressDestination(4);

    // mid-trip: car heading to 4, a new up call appears at floor 2
    // (must shorten to 2 before 4 — same direction, nearer first)
    let t = 0;
    let sawHeading = false;
    while (t < 30) {
        ev.tick(0.05);
        t += 0.05;
        if (ev.state === "MOVING" && ev.targetFloor === 4 && ev.direction === 1) {
            sawHeading = true;
            ev.callUp(2);
            break;
        }
    }
    check("direction: car was heading up to 4", sawHeading);

    const t2 = tickUntil(ev, (e) => e.currentFloor === 2 && e.state === "DOOR_OPEN", 60);
    check("direction: shortened trip, stopped at 2 first", t2 >= 0);

    // continue to 4, disembark
    const t4 = tickUntil(ev, (e) => e.currentFloor === 4 && e.state === "DOOR_OPEN", 60);
    check("direction: then reached destination 4", t4 >= 0);
    if (t4 >= 0) {
        ev.registerDisembark(r);
        ev.completeDisembark(r);
    }
    check("direction: passenger disembarked at 4", ev.passengers.length === 0);
}

// ============ Test 3: no full-car lobby starvation ============
{
    const ev = makeEv();
    // A full car of riders departs 0 heading up while 6 fresh up-calls
    // pile up at the lobby.
    for (let i = 0; i < 6; i++) ev.callUp(0);
    const riders = [];
    const t0 = tickUntil(ev, (e) => e.state === "DOOR_OPEN" && e.currentFloor === 0, 60);
    check("starvation: car served the initial lobby call", t0 >= 0);
    for (let i = 0; i < 4; i++) {
        const r = { floorIdx: 4 + (i % 2), id: i };
        riders.push(r);
        ev.reserveBoardingSpot(r);
        ev.completeBoard(r);
        ev.pressDestination(4 + (i % 2));
    }
    // ride to 4/5, all alight
    let t = 0;
    while (t < 120 && riders.some((r) => !r.disembarked)) {
        ev.tick(0.05);
        t += 0.05;
        for (const r of riders) {
            if (!r.disembarked && ev.state === "DOOR_OPEN" && ev.currentFloor === r.floorIdx) {
                ev.registerDisembark(r);
                ev.completeDisembark(r);
                r.disembarked = true;
            }
        }
    }
    check("starvation: all riders alighted", riders.every((r) => r.disembarked));

    // Now the car MUST return to the lobby for the waiting calls.
    const tBack = tickUntil(ev, (e) => e.currentFloor === 0 && e.state === "DOOR_OPEN", 120);
    check("starvation: car returned to lobby for waiting riders", tBack >= 0);
}

// ============ Test 4: opposite direction while moving (reverse at end) ============
{
    const ev = makeEv();
    // rider 0->4 starts the trip up
    ev.callUp(0);
    const t0 = tickUntil(ev, (e) => e.state === "DOOR_OPEN" && e.currentFloor === 0, 60);
    const r = { floorIdx: 4 };
    ev.reserveBoardingSpot(r);
    ev.completeBoard(r);
    ev.pressDestination(4);

    // while the car is moving up, a down call appears at floor 2 (opposite
    // direction of travel). It must NOT interrupt the upward trip.
    let sawMoving = false;
    let t = 0;
    while (t < 30) {
        ev.tick(0.05);
        t += 0.05;
        if (ev.state === "MOVING" && ev.direction === 1) {
            sawMoving = true;
            ev.callDown(2);
            break;
        }
    }
    check("reverse: car was moving up when the down call arrived", sawMoving);

    // car still goes up to 4 first
    const t4 = tickUntil(ev, (e) => e.currentFloor === 4 && e.state === "DOOR_OPEN", 60);
    check("reverse: up trip completed before handling opposite call", t4 >= 0);
    if (t4 >= 0) {
        ev.registerDisembark(r);
        ev.completeDisembark(r);
    }

    // then it comes back down for the floor-2 down call
    const t2 = tickUntil(ev, (e) => e.currentFloor === 2 && e.state === "DOOR_OPEN", 120);
    check("reverse: served the opposite-direction call afterwards", t2 >= 0);
}

// ============ Test 5: door hold during disembark / requeue on leave ============
{
    const ev = makeEv();
    ev.callUp(0);
    const t0 = tickUntil(ev, (e) => e.state === "DOOR_OPEN" && e.currentFloor === 0, 60);
    const r = { floorIdx: 3 };
    ev.reserveBoardingSpot(r);
    ev.completeBoard(r);
    ev.pressDestination(3);

    const t3 = tickUntil(ev, (e) => e.currentFloor === 3 && e.state === "DOOR_OPEN", 60);
    check("doorhold: reached floor 3", t3 >= 0);

    // register disembark, then tick past MIN_DOOR_OPEN_S: the door must
    // stay open (held by pendingDisembark)
    if (t3 >= 0) {
        ev.registerDisembark(r);
        const stateBefore = ev.state;
        ev.tick(ev.MIN_DOOR_OPEN_S + 1.0);
        check("doorhold: door held open while disembark pending",
            ev.state === "DOOR_OPEN" && stateBefore === "DOOR_OPEN");
        ev.completeDisembark(r);
        // now the door may close
        const tClosed = tickUntil(ev, (e) => e.state !== "DOOR_OPEN", 30);
        check("doorhold: door closed after disembark completed", tClosed >= 0);
    } else {
        check("doorhold: door held open while disembark pending", false);
        check("doorhold: door closed after disembark completed", false);
    }
}

// ============ Test 6: anti-starvation at a served floor ============
{
    const ev = makeEv();
    // serve floor 3 fully (a rider 0->3), then verify the car does NOT
    // immediately re-open for a floor-3 call that was already consumed,
    // and that it keeps scanning in the current direction for new work.
    ev.callUp(0);
    const t0 = tickUntil(ev, (e) => e.state === "DOOR_OPEN" && e.currentFloor === 0, 60);
    const r = { floorIdx: 3 };
    ev.reserveBoardingSpot(r);
    ev.completeBoard(r);
    ev.pressDestination(3);
    const t3 = tickUntil(ev, (e) => e.currentFloor === 3 && e.state === "DOOR_OPEN", 60);
    check("antiserv: reached floor 3", t3 >= 0);
    ev.registerDisembark(r);
    ev.completeDisembark(r);

    // after the doors close at 3 with no riders and no calls, the car must
    // go IDLE (not bounce back and forth opening/closing at 3)
    const tIdle = tickUntil(ev, (e) => e.state === "IDLE", 60);
    check("antiserv: car went IDLE at floor 3 when nothing else to do", tIdle >= 0 && ev.currentFloor === 3);

    // a brand-new up call at 0 now pulls the car back down
    ev.callUp(0);
    const tBack = tickUntil(ev, (e) => e.currentFloor === 0 && e.state === "DOOR_OPEN", 120);
    check("antiserv: new lobby call pulls car back", tBack >= 0);
}

// ============ Test 7: capacity hard limit ============
{
    const ev = makeEv({ floorCount: 6, maxCapacity: 4 });
    ev.callUp(0);
    const t0 = tickUntil(ev, (e) => e.state === "DOOR_OPEN" && e.currentFloor === 0, 60);
    const people = [];
    for (let i = 0; i < 7; i++) {
        const p = { id: i };
        people.push(p);
        ev.reserveBoardingSpot(p);
    }
    const accepted = people.filter((p) => p.spot !== undefined).length;
    check("capacity: exactly 4 of 7 boarders accepted", accepted === 4);
    check("capacity: 5th reservation rejected",
        people[4].spot === undefined && ev.currentCapacityFree() === 0);
    for (const p of people) {
        if (p.spot !== undefined) ev.completeBoard(p);
    }
    check("capacity: all accepted riders aboard", ev.passengers.length === 4);
}

// ---------------- summary ----------------
console.log("");
console.log("RESULTS: " + passCount + " passed, " + failCount + " failed, " + (passCount + failCount) + " total");
if (failCount > 0) {
    console.log("Failed tests: " + failures.join(", "));
    process.exit(1);
} else {
    console.log("All elevator logic tests passed.");
}

