// elevator_logic.js — pure elevator scheduler/state machine.
// No Three.js, no DOM, no canvas. Runs in the browser (window.ElevatorLogic)
// and under Node (module.exports) for elevator_logic_test.js.

(function (root) {
    "use strict";

    const STATES = {
        IDLE: "IDLE",
        MOVING: "MOVING",
        DOOR_OPENING: "DOOR_OPENING",
        DOOR_OPEN: "DOOR_OPEN",
        DOOR_CLOSING: "DOOR_CLOSING"
    };

    const DOOR_ANIM_S = 1.2;      // door opening/closing duration (seconds)
    const MIN_DOOR_OPEN_S = 2.0;  // doors stay open at least this long
    const MAX_DOOR_OPEN_S = 12.0; // safety cap even if a boarder never completes
    const SPEED = 2.2;            // car speed, world units per second

    // Logical interior spots (car-local coordinates; car floor at y=0).
    const SPOT_POSITIONS = [
        { x: -0.7, y: 0, z: -0.7 },
        { x: 0.7, y: 0, z: -0.7 },
        { x: -0.7, y: 0, z: 0.45 },
        { x: 0.7, y: 0, z: 0.45 }
    ];

    class ElevatorLogic {
        constructor(opts) {
            opts = opts || {};
            this.floorCount = opts.floorCount !== undefined ? opts.floorCount : 6;
            this.maxCapacity = opts.maxCapacity !== undefined ? opts.maxCapacity : 4;
            this.floorHeight = opts.floorHeight !== undefined ? opts.floorHeight : 3.4;

            this.DOOR_ANIM_S = DOOR_ANIM_S;
            this.MIN_DOOR_OPEN_S = MIN_DOOR_OPEN_S;
            this.MAX_DOOR_OPEN_S = MAX_DOOR_OPEN_S;
            this.SPEED = SPEED;

            this.reset();
        }

        reset() {
            this.state = STATES.IDLE;
            this.y = 0;                    // car floor world height
            this.currentFloor = 0;
            this.targetFloor = null;
            this.direction = 0;            // +1 up, -1 down, 0 idle
            this.upCalls = new Set();
            this.downCalls = new Set();
            this.destinations = new Set();
            this.passengers = new Set();
            this.pendingBoarders = new Set();
            this.pendingDisembark = new Set();
            this.spotOccupancy = new Array(SPOT_POSITIONS.length).fill(null);
            this.doorProgress = 0;         // 0 closed .. 1 open
            this.doorOpenTimer = 0;
            this.doorTimer = 0;
            this.servedThisDoorCycle = false;
            this.lastServedFloor = null;   // guard: floor served by the most recent door cycle
        }

        // ---- public call/destination API -------------------------------

        callUp(floor) {
            if (floor >= 0 && floor < this.floorCount) this.upCalls.add(floor);
        }

        callDown(floor) {
            if (floor >= 0 && floor < this.floorCount) this.downCalls.add(floor);
        }

        pressDestination(floor) {
            if (floor >= 0 && floor < this.floorCount && floor !== null) {
                if (floor !== this.currentFloor || this.state === STATES.MOVING) {
                    this.destinations.add(floor);
                } else if (this.state !== STATES.DOOR_OPEN && this.state !== STATES.DOOR_OPENING) {
                    this.destinations.add(floor);
                }
                // pressing your current floor while doors are open is a no-op
            }
        }

        isAcceptingAt(floor, direction) {
            if (this.state !== STATES.DOOR_OPEN) return false;
            if (this.currentFloor !== floor) return false;
            if (this.direction === 0 || direction === 0) return true;
            if (this.direction === direction) return true;
            // accept opposite-direction boarders only when no more work ahead
            return !this._hasWorkInDirection(this.direction, floor);
        }

        currentCapacityFree() {
            return this.maxCapacity - (this.passengers.size + this.pendingBoarders.size);
        }

        reserveBoardingSpot(person) {
            if (this.currentCapacityFree() <= 0) return null;
            for (let i = 0; i < this.spotOccupancy.length; i++) {
                if (this.spotOccupancy[i] === null) {
                    this.spotOccupancy[i] = person;
                    this.pendingBoarders.add(person);
                    const p = SPOT_POSITIONS[i];
                    return { index: i, x: p.x, y: p.y, z: p.z };
                }
            }
            return null;
        }

        completeBoard(person) {
            if (this.pendingBoarders.has(person)) {
                this.pendingBoarders.delete(person);
                this.passengers.add(person);
            }
        }

        cancelBoard(person) {
            // boarder gave up (car left, etc.) — free the spot
            this.pendingBoarders.delete(person);
            for (let i = 0; i < this.spotOccupancy.length; i++) {
                if (this.spotOccupancy[i] === person) this.spotOccupancy[i] = null;
            }
        }

        registerDisembark(person) {
            if (this.passengers.has(person)) {
                this.pendingDisembark.add(person);
            }
        }

        completeDisembark(person) {
            this.pendingDisembark.delete(person);
            this.passengers.delete(person);
            for (let i = 0; i < this.spotOccupancy.length; i++) {
                if (this.spotOccupancy[i] === person) this.spotOccupancy[i] = null;
            }
        }

        // ---- internal helpers ------------------------------------------

        _hasWorkInDirection(dir, fromFloor) {
            if (dir > 0) {
                for (let f = fromFloor + 1; f < this.floorCount; f++) {
                    if (this.destinations.has(f) || this.upCalls.has(f) || this.downCalls.has(f)) return true;
                }
            } else if (dir < 0) {
                for (let f = fromFloor - 1; f >= 0; f--) {
                    if (this.destinations.has(f) || this.upCalls.has(f) || this.downCalls.has(f)) return true;
                }
            }
            return false;
        }

        _nearestStopInDirection(dir, fromFloor) {
            // Nearest destination or matching-direction call strictly ahead.
            // A non-matching call at the far end is also pickable (turnaround).
            if (dir === 0) return null;
            let nearestServe = null;   // destination or matching call
            let farthestCall = null;   // any call ahead (turnaround target)
            if (dir > 0) {
                for (let f = fromFloor + 1; f < this.floorCount; f++) {
                    if (nearestServe === null && (this.destinations.has(f) || this.upCalls.has(f))) nearestServe = f;
                    if (this.destinations.has(f) || this.upCalls.has(f) || this.downCalls.has(f)) farthestCall = f;
                }
            } else {
                for (let f = fromFloor - 1; f >= 0; f--) {
                    if (nearestServe === null && (this.destinations.has(f) || this.downCalls.has(f))) nearestServe = f;
                    if (this.destinations.has(f) || this.upCalls.has(f) || this.downCalls.has(f)) farthestCall = f;
                }
            }
            if (nearestServe !== null) return nearestServe;
            return farthestCall; // ride to the far call and reverse there
        }

        _nearestAnyStop(fromFloor, excludeFloor) {
            let best = null, bestDist = Infinity;
            for (let f = 0; f < this.floorCount; f++) {
                if (f === excludeFloor) continue;
                if (this.destinations.has(f) || this.upCalls.has(f) || this.downCalls.has(f)) {
                    const d = Math.abs(f - fromFloor);
                    if (d < bestDist) { bestDist = d; best = f; }
                }
            }
            return best;
        }

        _pickNextTarget() {
            // Called at door-close (and from IDLE). Decide the next target floor.
            const here = this.currentFloor;
            const hasRiders = this.passengers.size > 0 || this.pendingBoarders.size > 0;

            // Passenger destinations outrank everything else, especially
            // same-floor hall calls (no full-car lobby starvation).
            if (hasRiders && this.destinations.size > 0) {
                let target = null;
                if (this.direction !== 0) {
                    target = this._nearestDestInDirection(this.direction, here);
                    if (target === null) target = this._nearestDestInDirection(-this.direction, here);
                }
                if (target === null) {
                    let bestDist = Infinity;
                    this.destinations.forEach((f) => {
                        const d = Math.abs(f - here);
                        if (f !== here && d < bestDist) { bestDist = d; target = f; }
                    });
                }
                if (target !== null) return target;
            }

            // Continue in current direction if there's work ahead.
            if (this.direction !== 0) {
                const ahead = this._nearestStopInDirection(this.direction, here);
                if (ahead !== null) return ahead;
                const behind = this._nearestStopInDirection(-this.direction, here);
                if (behind !== null) return behind;
            }

            // Same-floor hall call while idle/empty. Skipped right after a
            // door cycle at this floor (servedThisDoorCycle) so leftover
            // re-pressed calls can't force an immediate reopen; once the car
            // is IDLE that flag clears and a fresh call reopens normally.
            if (!hasRiders && !this.servedThisDoorCycle &&
                (this.upCalls.has(here) || this.downCalls.has(here))) {
                return here;
            }

            // Nearest active call/destination anywhere else.
            const exclude = this.servedThisDoorCycle ? here : -1;
            const any = this._nearestAnyStop(here, exclude);
            if (any !== null) return any;
            return null;
        }

        _nearestDestInDirection(dir, fromFloor) {
            if (dir > 0) {
                for (let f = fromFloor + 1; f < this.floorCount; f++) {
                    if (this.destinations.has(f)) return f;
                }
            } else if (dir < 0) {
                for (let f = fromFloor - 1; f >= 0; f--) {
                    if (this.destinations.has(f)) return f;
                }
            }
            return null;
        }

        _arriveServe() {
            // Door-open arrival housekeeping: clear served stops.
            const here = this.currentFloor;
            this.destinations.delete(here);
            if (this.direction > 0) {
                this.upCalls.delete(here);
                if (!this._hasWorkInDirection(1, here)) {
                    // no more work ahead — also serve the down call here, and reverse intent
                    this.downCalls.delete(here);
                    if (this._hasWorkInDirection(-1, here)) this.direction = -1;
                    else this.direction = 0;
                }
            } else if (this.direction < 0) {
                this.downCalls.delete(here);
                if (!this._hasWorkInDirection(-1, here)) {
                    this.upCalls.delete(here);
                    if (this._hasWorkInDirection(1, here)) this.direction = 1;
                    else this.direction = 0;
                }
            } else {
                // idle arrival: infer direction from remaining work, clear both
                if (this.upCalls.has(here) && this.downCalls.has(here)) {
                    const up = this._hasWorkInDirection(1, here);
                    const down = this._hasWorkInDirection(-1, here);
                    this.upCalls.delete(here);
                    this.downCalls.delete(here);
                    this.direction = up ? 1 : (down ? -1 : 0);
                } else if (this.upCalls.has(here)) {
                    this.upCalls.delete(here);
                    this.direction = 1;
                } else if (this.downCalls.has(here)) {
                    this.downCalls.delete(here);
                    this.direction = -1;
                }
            }
            this.servedThisDoorCycle = true;
            this.lastServedFloor = here;
        }

        // ---- main tick --------------------------------------------------

        tick(dt) {
            if (dt <= 0) return;
            // Cap a single physics step; long frames advance in sub-steps so
            // a high timeScale doesn't tunnel the car through floors.
            let remaining = dt;
            const MAX_STEP = 0.25;
            while (remaining > 0) {
                const step = Math.min(MAX_STEP, remaining);
                const wasOpen = this.state === STATES.DOOR_OPEN;
                this._step(step);
                remaining -= step;
                // Yield the moment the doors reach DOOR_OPEN: at high time
                // scales a whole frame can exceed the min-open window, and
                // riders/waiters need one observable DOOR_OPEN frame to
                // register boarding/disembarking before the timer runs.
                if (!wasOpen && this.state === STATES.DOOR_OPEN) break;
            }
        }

        _step(dt) {
            switch (this.state) {
                case STATES.IDLE: {
                    const target = this._pickNextTarget();
                    if (target === null) break;
                    if (target === this.currentFloor) {
                        // serve a hall call at this floor
                        if (this.direction === 0) {
                            if (this.upCalls.has(target) && !this.downCalls.has(target)) this.direction = 1;
                            else if (this.downCalls.has(target) && !this.upCalls.has(target)) this.direction = -1;
                        }
                        this.targetFloor = target;
                        this.state = STATES.DOOR_OPENING;
                        this.doorTimer = 0;
                    } else {
                        this.targetFloor = target;
                        this.direction = target > this.currentFloor ? 1 : -1;
                        this.state = STATES.MOVING;
                        this.servedThisDoorCycle = false;
                    }
                    break;
                }

                case STATES.MOVING: {
                    // Re-evaluate: is there a closer stop in the same direction?
                    if (this.direction > 0) {
                        const next = Math.ceil((this.y + 1e-6) / this.floorHeight);
                        for (let f = next; f < this.targetFloor; f++) {
                            if (this.destinations.has(f) ||
                                (this.upCalls.has(f) && this.currentCapacityFree() > 0)) {
                                // only shorten if we can still decelerate "in time"
                                if (f * this.floorHeight >= this.y - 1e-6) {
                                    this.targetFloor = f;
                                    break;
                                }
                            }
                        }
                    } else if (this.direction < 0) {
                        const next = Math.floor((this.y - 1e-6) / this.floorHeight);
                        for (let f = next; f > this.targetFloor; f--) {
                            if (this.destinations.has(f) ||
                                (this.downCalls.has(f) && this.currentCapacityFree() > 0)) {
                                if (f * this.floorHeight <= this.y + 1e-6) {
                                    this.targetFloor = f;
                                    break;
                                }
                            }
                        }
                    }

                    const targetY = this.targetFloor * this.floorHeight;
                    const dy = targetY - this.y;
                    const move = SPEED * dt;
                    if (Math.abs(dy) <= move) {
                        this.y = targetY;
                        this.currentFloor = this.targetFloor;
                        this.state = STATES.DOOR_OPENING;
                        this.doorTimer = 0;
                    } else {
                        this.y += Math.sign(dy) * move;
                        // keep currentFloor as the nearest floor for indicators
                        this.currentFloor = Math.round(this.y / this.floorHeight);
                    }
                    break;
                }

                case STATES.DOOR_OPENING: {
                    this.doorTimer += dt;
                    this.doorProgress = Math.min(1, this.doorTimer / DOOR_ANIM_S);
                    if (this.doorProgress >= 1) {
                        this.state = STATES.DOOR_OPEN;
                        this.doorOpenTimer = 0;
                        this._arriveServe();
                    }
                    break;
                }

                case STATES.DOOR_OPEN: {
                    this.doorOpenTimer += dt;
                    const held = this.pendingBoarders.size > 0 || this.pendingDisembark.size > 0;
                    const minElapsed = this.doorOpenTimer >= MIN_DOOR_OPEN_S;
                    const capFired = this.doorOpenTimer >= MAX_DOOR_OPEN_S;
                    if ((minElapsed && !held) || capFired) {
                        if (capFired && held) {
                            // safety: abandon stuck handshakes so the car can move on
                            this.pendingDisembark.clear();
                            this.pendingBoarders.forEach((p) => this.cancelBoard(p));
                        }
                        this.state = STATES.DOOR_CLOSING;
                        this.doorTimer = 0;
                    }
                    break;
                }

                case STATES.DOOR_CLOSING: {
                    this.doorTimer += dt;
                    this.doorProgress = Math.max(0, 1 - this.doorTimer / DOOR_ANIM_S);
                    if (this.doorProgress <= 0) {
                        const target = this._pickNextTarget();
                        if (target === null) {
                            this.state = STATES.IDLE;
                            this.targetFloor = null;
                            this.direction = 0;
                            this.servedThisDoorCycle = false;
                        } else if (target === this.currentFloor) {
                            // Guard: never reopen at the floor just served while
                            // riders/destinations exist (lobby starvation).
                            if (this.lastServedFloor === this.currentFloor &&
                                (this.destinations.size > 0 || this.passengers.size > 0)) {
                                // force pick a destination instead
                                let alt = null, bestDist = Infinity;
                                this.destinations.forEach((f) => {
                                    if (f !== this.currentFloor) {
                                        const d = Math.abs(f - this.currentFloor);
                                        if (d < bestDist) { bestDist = d; alt = f; }
                                    }
                                });
                                if (alt !== null) {
                                    this.targetFloor = alt;
                                    this.direction = alt > this.currentFloor ? 1 : -1;
                                    this.state = STATES.MOVING;
                                    this.servedThisDoorCycle = false;
                                } else {
                                    this.state = STATES.IDLE;
                                    this.targetFloor = null;
                                    this.direction = 0;
                                    this.servedThisDoorCycle = false;
                                }
                            } else {
                                this.state = STATES.DOOR_OPENING;
                                this.doorTimer = 0;
                                this.targetFloor = target;
                            }
                        } else {
                            this.targetFloor = target;
                            this.direction = target > this.currentFloor ? 1 : -1;
                            this.state = STATES.MOVING;
                            this.servedThisDoorCycle = false;
                        }
                    }
                    break;
                }
            }
        }
    }

    ElevatorLogic.STATES = STATES;
    ElevatorLogic.SPOT_POSITIONS = SPOT_POSITIONS;

    root.ElevatorLogic = ElevatorLogic;
    if (typeof module !== "undefined" && module.exports) {
        module.exports = { ElevatorLogic };
    }
})(typeof window !== "undefined" ? window : globalThis);

// elevator_logic_test.js — deterministic Node tests for ElevatorLogic.
// Run: node elevator_logic_test.js   (no npm deps, Node built-ins only)

const assert = require("assert");
const { ElevatorLogic } = require("./elevator_logic.js");

const DT = 0.1; // fixed deterministic tick
const results = [];

function test(name, fn) {
    try {
        fn();
        results.push({ name, ok: true });
        console.log(`PASS  ${name}`);
    } catch (err) {
        results.push({ name, ok: false, err });
        console.log(`FAIL  ${name}`);
        console.log(`      ${err.message}`);
    }
}

// --- helpers ---------------------------------------------------------------

function tickUntil(ev, pred, maxTicks, label) {
    maxTicks = maxTicks || 5000;
    for (let i = 0; i < maxTicks; i++) {
        if (pred(ev)) return i;
        ev.tick(DT);
    }
    throw new Error(`tickUntil(${label || "predicate"}) exceeded ${maxTicks} ticks ` +
        `(state=${ev.state} floor=${ev.currentFloor} target=${ev.targetFloor})`);
}

function runUntilDoorOpenAt(ev, floor, maxTicks) {
    return tickUntil(ev,
        (e) => e.state === "DOOR_OPEN" && e.currentFloor === floor,
        maxTicks, `DOOR_OPEN@${floor}`);
}

function runUntilDoorClosed(ev, maxTicks) {
    // run until doors finish closing (state leaves DOOR_OPEN/DOOR_CLOSING)
    tickUntil(ev, (e) => e.state === "DOOR_OPEN", maxTicks, "reach DOOR_OPEN");
    return tickUntil(ev,
        (e) => e.state === "IDLE" || e.state === "MOVING",
        maxTicks, "doors closed");
}

function boardRider(ev, name, destFloor) {
    const spot = ev.reserveBoardingSpot(name);
    assert.ok(spot, `${name} should get a boarding spot`);
    ev.completeBoard(name);
    if (destFloor !== undefined && destFloor !== null) ev.pressDestination(destFloor);
    return spot;
}

// --- 1. Lobby rush with more callers than capacity ---------------------------

test("lobby rush: full car leaves floor 0 despite re-pressed UP calls", () => {
    const ev = new ElevatorLogic({ floorCount: 6, maxCapacity: 4 });
    ev.callUp(0);
    runUntilDoorOpenAt(ev, 0);

    // four riders board, press upper floors
    boardRider(ev, "p1", 2);
    boardRider(ev, "p2", 3);
    boardRider(ev, "p3", 5);
    boardRider(ev, "p4", 3);
    assert.strictEqual(ev.currentCapacityFree(), 0, "car should be full");
    assert.strictEqual(ev.reserveBoardingSpot("p5"), null, "5th rider must be rejected");

    // leftover lobby waiters keep pressing UP every tick
    let sawReopenAtZero = false;
    let leftFloorZero = false;
    for (let i = 0; i < 600; i++) {
        ev.callUp(0); // re-press like real waiters
        const prevState = ev.state;
        ev.tick(DT);
        if (prevState === "DOOR_CLOSING" && ev.state === "DOOR_OPENING" && ev.currentFloor === 0) {
            sawReopenAtZero = true;
        }
        if (ev.state === "MOVING" && ev.targetFloor > 0) { leftFloorZero = true; break; }
    }
    assert.ok(!sawReopenAtZero, "doors must not reopen at floor 0 while destinations exist");
    assert.ok(leftFloorZero, "car must depart upward with its passengers");
    assert.ok(ev.targetFloor > 0, `next target must be above floor 0, got ${ev.targetFloor}`);
    assert.ok(ev.upCalls.has(0), "leftover UP call stays queued for the next trip");
});

// --- 2. Passenger destinations outrank same-floor hall calls -----------------

test("passenger destinations outrank same-floor hall calls", () => {
    const ev = new ElevatorLogic({ floorCount: 6, maxCapacity: 4 });
    ev.callUp(0);
    runUntilDoorOpenAt(ev, 0);
    boardRider(ev, "rider", 4);

    // a same-floor hall call appears right as the doors are closing
    tickUntil(ev, (e) => e.state === "DOOR_CLOSING", 500, "DOOR_CLOSING");
    ev.callUp(0);
    let reopened = false;
    for (let i = 0; i < 400; i++) {
        const prev = ev.state;
        ev.tick(DT);
        if (prev === "DOOR_CLOSING" && ev.state === "DOOR_OPENING" && ev.currentFloor === 0) reopened = true;
        if (ev.state === "MOVING") break;
    }
    assert.ok(!reopened, "must not reopen at the same floor with a passenger aboard");
    assert.strictEqual(ev.targetFloor, 4, "must head to the passenger's destination");
});

// --- 3. Repeated hall-call pressing cannot starve riders ---------------------

test("repeated callUp(0) cannot starve riders' destinations", () => {
    const ev = new ElevatorLogic({ floorCount: 6, maxCapacity: 4 });
    ev.callUp(0);
    runUntilDoorOpenAt(ev, 0);
    boardRider(ev, "a", 3);
    boardRider(ev, "b", 5);

    let reachedDest = false;
    for (let i = 0; i < 3000; i++) {
        ev.callUp(0); // hammer the lobby button every tick
        ev.tick(DT);
        if (ev.state === "DOOR_OPEN" && (ev.currentFloor === 3 || ev.currentFloor === 5)) {
            reachedDest = true;
            break;
        }
    }
    assert.ok(reachedDest, "car must still reach a passenger destination");
});

// --- 4. Opposite-direction calls wait their turn -----------------------------

test("down call below does not reverse an upward car with work above", () => {
    const ev = new ElevatorLogic({ floorCount: 6, maxCapacity: 4 });
    ev.callUp(0);
    runUntilDoorOpenAt(ev, 0);
    boardRider(ev, "up1", 4);
    boardRider(ev, "up2", 5);

    runUntilDoorClosed(ev);
    assert.strictEqual(ev.direction, 1, "car should be heading up");

    // While moving up, a DOWN call arrives at floor 1 (below / behind)
    ev.callDown(1);
    ev.callDown(2);

    // Car must serve 4 then 5 before turning around for the down calls.
    runUntilDoorOpenAt(ev, 4);
    assert.ok(ev.downCalls.has(1) && ev.downCalls.has(2), "down calls still queued at floor 4");
    runUntilDoorOpenAt(ev, 5);
    // after the top, it may reverse and serve the down calls
    tickUntil(ev, (e) => e.state === "DOOR_OPEN" && (e.currentFloor === 2 || e.currentFloor === 1),
        8000, "serve down calls after reversing");
    assert.ok(true);
});

// --- 5. Door hold and safety cap ---------------------------------------------

test("doors hold for pending boarders, then MAX_DOOR_OPEN_S cap closes them", () => {
    const ev = new ElevatorLogic({ floorCount: 6, maxCapacity: 4 });
    ev.callUp(0);
    runUntilDoorOpenAt(ev, 0);

    const spot = ev.reserveBoardingSpot("slowpoke");
    assert.ok(spot, "slowpoke gets a spot");
    // never completes boarding…

    // after MIN_DOOR_OPEN_S the doors must STILL be open (held by pendingBoarders)
    const minTicks = Math.ceil((ev.MIN_DOOR_OPEN_S + 0.5) / DT);
    for (let i = 0; i < minTicks; i++) ev.tick(DT);
    assert.strictEqual(ev.state, "DOOR_OPEN", "doors held open past min time by pending boarder");

    // …but MAX_DOOR_OPEN_S eventually force-closes
    const capTicks = Math.ceil((ev.MAX_DOOR_OPEN_S + 1.0) / DT);
    for (let i = 0; i < capTicks; i++) ev.tick(DT);
    assert.notStrictEqual(ev.state, "DOOR_OPEN", "safety cap must close the doors");
    assert.strictEqual(ev.pendingBoarders.size, 0, "stuck boarder abandoned");
    assert.strictEqual(ev.spotOccupancy.filter(Boolean).length, 0, "spot released");

    // also verify a disembarker holds the doors
    const ev2 = new ElevatorLogic({ floorCount: 6, maxCapacity: 4 });
    ev2.callUp(0);
    runUntilDoorOpenAt(ev2, 0);
    boardRider(ev2, "r", 3);
    runUntilDoorOpenAt(ev2, 3);
    ev2.registerDisembark("r");
    const holdTicks = Math.ceil((ev2.MIN_DOOR_OPEN_S + 1.0) / DT);
    for (let i = 0; i < holdTicks; i++) ev2.tick(DT);
    assert.strictEqual(ev2.state, "DOOR_OPEN", "doors held for pending disembark");
    ev2.completeDisembark("r");
    tickUntil(ev2, (e) => e.state !== "DOOR_OPEN", 1000, "close after disembark completes");
});

// --- 6. Destination preserved across the action handshake --------------------

test("rider 0→5: destination survives the WAIT/ENTER/PRESS/WAIT handshake", () => {
    const ev = new ElevatorLogic({ floorCount: 6, maxCapacity: 4 });

    // WAIT_AT_PANEL: rider on floor 0 wants floor 5 (direction up)
    const rider = { name: "rider", toFloor: 5 };
    ev.callUp(0);
    tickUntil(ev, (e) => e.isAcceptingAt(0, 1) && e.currentCapacityFree() > 0, 2000, "accepting at 0 up");

    // ENTER_ELEVATOR(toFloor=5): reserve, board
    const spot = ev.reserveBoardingSpot(rider);
    assert.ok(spot, "spot reserved");
    assert.ok(typeof spot.index === "number" && "x" in spot && "y" in spot && "z" in spot,
        "spot is a plain {index,x,y,z} object");
    ev.completeBoard(rider);

    // PRESS_FLOOR uses the plan's toFloor — NOT floor+direction (which would be 1)
    ev.pressDestination(rider.toFloor);
    assert.ok(ev.destinations.has(5), "destination 5 registered");
    assert.ok(!ev.destinations.has(1), "must not register floor 1 (direction-derived bug)");

    // WAIT_FOR_FLOOR(5)
    runUntilDoorOpenAt(ev, 5, 8000);
    assert.strictEqual(ev.currentFloor, 5, "car arrived at the rider's actual destination");

    // EXIT_ELEVATOR
    ev.registerDisembark(rider);
    assert.ok(ev.pendingDisembark.has(rider), "disembark registered holds doors");
    ev.completeDisembark(rider);
    assert.strictEqual(ev.passengers.size, 0, "rider out");
});

// --- 7. Reset clears phantom state -------------------------------------------

test("reset() clears phantom state", () => {
    const ev = new ElevatorLogic({ floorCount: 6, maxCapacity: 4 });
    ev.callUp(0);
    runUntilDoorOpenAt(ev, 0);
    boardRider(ev, "x", 4);
    const ghost = ev.reserveBoardingSpot("ghost");
    assert.ok(ghost, "ghost pending boarder");
    ev.callDown(5);
    ev.callUp(2);
    for (let i = 0; i < 30; i++) ev.tick(DT);

    ev.reset();
    assert.strictEqual(ev.upCalls.size, 0, "upCalls cleared");
    assert.strictEqual(ev.downCalls.size, 0, "downCalls cleared");
    assert.strictEqual(ev.destinations.size, 0, "destinations cleared");
    assert.strictEqual(ev.passengers.size, 0, "passengers cleared");
    assert.strictEqual(ev.pendingBoarders.size, 0, "pendingBoarders cleared");
    assert.strictEqual(ev.pendingDisembark.size, 0, "pendingDisembark cleared");
    assert.strictEqual(ev.spotOccupancy.filter(Boolean).length, 0, "spots free");
    assert.strictEqual(ev.direction, 0, "direction reset");
    assert.strictEqual(ev.targetFloor, null, "target cleared");
    assert.strictEqual(ev.currentFloor, 0, "parked at floor 0");
    assert.strictEqual(ev.y, 0, "car at ground height");
    assert.strictEqual(ev.state, "IDLE", "idle");
    assert.strictEqual(ev.doorProgress, 0, "doors closed");
    assert.strictEqual(ev.doorOpenTimer, 0, "door open timer cleared");
    assert.strictEqual(ev.doorTimer, 0, "door timer cleared");

    // and the machine still works after reset
    ev.callUp(3);
    runUntilDoorOpenAt(ev, 3, 8000);
});

